"""Snapping clock times to a fixed step, for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """The step must be a positive number of minutes that divides an hour."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"step must divide an hour evenly: {step}")

def round_minute(minute: int, step: int) -> int:
    """Nearest multiple of step, with exact halves going up."""
    count, rest = divmod(minute, step)
    return (count + (rest * 2 >= step)) * step

def round_span(span: Span, step: int) -> Span:
    """Round both ends. A span that collapses to nothing raises ValueError."""
    return Span(round_minute(span.start, step), round_minute(span.end, step))

def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"

def round_labels(spans: Iterable[Span], step: int) -> List[str]:
    """One label per span, in order, after rounding to the step."""
    check_step(step)
    return [span_label(round_span(span, step)) for span in spans]

