import unittest

from hourglass.rounding import span_label, round_minute, round_labels
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundMinuteTests(unittest.TestCase):
    def test_nearest(self):
        self.assertEqual(round_minute(62, 15), 60)
        self.assertEqual(round_minute(68, 15), 75)

    def test_half_goes_up(self):
        self.assertEqual(round_minute(7 * 60 + 30, 15), 7 * 60 + 30)
        self.assertEqual(round_minute(45, 30), 60)
        self.assertEqual(round_minute(15, 30), 30)

class LabelTests(unittest.TestCase):
    def test_label(self):
        label = span_label(parse_span("09:00-17:15"))
        self.assertEqual(label, "09:00-17:15 (8h 15m)")

    def test_rounds_each_end(self):
        spans = [parse_span("08:58-17:08"), parse_span("12:07-12:53")]
        self.assertEqual(
            round_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "12:00-13:00 (1h 0m)"]
        )

    def test_end_of_day(self):
        labels = round_labels([Span(23 * 60, 24 * 60 - 2)], 15)
        self.assertEqual(labels, ["23:00-24:00 (1h 0m)"])

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])

class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps(self):
        for step in (1, 5, 6, 10, 15, 30, 60):
            self.assertEqual(len(round_labels([Span(0, 120)], step)), 1)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 64)], 15)

if __name__ == "__main__":
    unittest.main()
